ALTER TABLE public.patients ADD CONSTRAINT patients_portal_tenant_key UNIQUE (tenant_id,id);
CREATE TABLE public.portal_patient_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), patient_id uuid NOT NULL, user_id uuid UNIQUE, role text NOT NULL DEFAULT 'patient' CHECK(role='patient'), starter_proposed boolean NOT NULL DEFAULT false, clinic_label text NOT NULL DEFAULT '', cosmetic_history_count integer NOT NULL DEFAULT 0, medication text, initial_weight_kg numeric, goal_weight_kg numeric, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, UNIQUE(tenant_id,patient_id), FOREIGN KEY(tenant_id,patient_id) REFERENCES public.patients(tenant_id,id));
GRANT SELECT ON public.portal_patient_access TO authenticated; GRANT ALL ON public.portal_patient_access TO service_role;
ALTER TABLE public.portal_patient_access ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.portal_patient_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.patient_id FROM public.portal_patient_access a JOIN public.patients p ON p.id=a.patient_id AND p.tenant_id=a.tenant_id WHERE a.user_id=auth.uid() AND a.tenant_id::text=(auth.jwt()->'app_metadata'->>'active_tenant') AND p.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.tenant_memberships m WHERE m.user_id=auth.uid()) AND NOT EXISTS(SELECT 1 FROM public.group_admins g WHERE g.user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.portal_patient_id() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.portal_patient_id() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.current_tenant() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT m.tenant_id FROM public.tenant_memberships m JOIN public.profiles p ON p.id=m.user_id AND NOT p.blocked WHERE m.user_id=auth.uid() AND m.tenant_id::text=(auth.jwt()->'app_metadata'->>'active_tenant')), CASE WHEN public.is_group_admin() THEN nullif(auth.jwt()->'app_metadata'->>'active_tenant','')::uuid END, (SELECT a.tenant_id FROM public.portal_patient_access a WHERE a.patient_id=public.portal_patient_id() AND a.user_id=auth.uid())) $$;
CREATE POLICY portal_access_own ON public.portal_patient_access FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND patient_id=public.portal_patient_id() AND user_id=auth.uid());
CREATE POLICY portal_patient_own ON public.patients FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND id=public.portal_patient_id() AND deleted_at IS NULL);
CREATE TABLE public.portal_login_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), patient_id uuid, email text NOT NULL, token_hash text NOT NULL UNIQUE CHECK(token_hash ~ '^[a-f0-9]{64}$'), pending_booking_id uuid REFERENCES public.appointments(id), expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, FOREIGN KEY(tenant_id,patient_id) REFERENCES public.patients(tenant_id,id));
GRANT ALL ON public.portal_login_tokens TO service_role; ALTER TABLE public.portal_login_tokens ENABLE ROW LEVEL SECURITY;
CREATE INDEX portal_token_rate ON public.portal_login_tokens(tenant_id,email,created_at);
CREATE TABLE public.ma_packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL DEFAULT public.current_tenant() REFERENCES public.tenants(id), patient_id uuid NOT NULL, order_id uuid NOT NULL, start_date date NOT NULL, months integer NOT NULL CHECK(months IN (1,2,3,6)), strengths jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid, FOREIGN KEY(tenant_id,patient_id) REFERENCES public.patients(tenant_id,id));
GRANT SELECT ON public.ma_packages TO authenticated; GRANT ALL ON public.ma_packages TO service_role; ALTER TABLE public.ma_packages ENABLE ROW LEVEL SECURITY;
CREATE POLICY portal_packages_own ON public.ma_packages FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND patient_id=public.portal_patient_id());
CREATE POLICY portal_measurements_own ON public.measurements FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND patient_id=public.portal_patient_id());
CREATE TABLE public.portal_config (tenant_id uuid PRIMARY KEY DEFAULT public.current_tenant() REFERENCES public.tenants(id), content jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_by uuid);
GRANT SELECT ON public.portal_config TO authenticated; GRANT ALL ON public.portal_config TO service_role; ALTER TABLE public.portal_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY portal_config_own ON public.portal_config FOR SELECT TO authenticated USING(tenant_id=public.current_tenant() AND public.portal_patient_id() IS NOT NULL);
CREATE OR REPLACE FUNCTION public.portal_claim_token(_hash text,_tenant uuid) RETURNS SETOF public.portal_login_tokens LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.portal_login_tokens SET used_at=now(),updated_at=now() WHERE token_hash=_hash AND tenant_id=_tenant AND used_at IS NULL AND expires_at>now() RETURNING * $$;
REVOKE ALL ON FUNCTION public.portal_claim_token(text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.portal_claim_token(text,uuid) TO service_role;
